// AI-Personalized Pricing per Visitor
// Dynamically adjusts pricing based on visitor behavior, location, and intent.
// No competing SaaS offers real-time per-visitor AI pricing.

const pricingModel = require('../constants/pricingModel.json');
const visitorProfile = require('./visitorProfile');

function getPersonalizedPrice(basePrice, visitorId) {
  const profile = visitorProfile.getProfile(visitorId);
  let multiplier = 1.0;
  // Adjust based on engagement score (0-100)
  if (profile.engagementScore > 80) multiplier *= 0.9; // loyal visitor discount
  else if (profile.engagementScore < 20) multiplier *= 1.1; // new visitor premium
  // Adjust based on location purchasing power
  const ppp = pricingModel.pppFactors[profile.country] || 1.0;
  multiplier *= ppp;
  // Adjust based on time of day (off-peak discount)
  const hour = new Date().getHours();
  if (hour >= 2 && hour <= 5) multiplier *= 0.85;
  // Ensure price stays within bounds
  const finalPrice = Math.round(basePrice * multiplier * 100) / 100;
  return Math.max(finalPrice, pricingModel.minPrice);
}

module.exports = { getPersonalizedPrice };
